ndex":5},{"boost_hits":33,"item_id":"sunsteel_damage_potion","strength_pct":12,"tier_index":6},{"boost_hits":33,"item_id":"runite_damage_potion","strength_pct":12,"tier_index":7},{"boost_hits":35,"item_id":"shadow_venom","strength_pct":13,"tier_index":8},{"boost_hits":35,"item_id":"froststeel_damage_potion","strength_pct":13,"tier_index":9},{"boost_hits":35,"item_id":"wyrmsteel_damage_potion","strength_pct":14,"tier_index":10},{"boost_hits":35,"item_id":"frostfire_brew","strength_pct":15,"tier_index":11},{"boost_hits":35,"item_id":"starsteel_damage_potion","strength_pct":16,"tier_index":12},{"boost_hits":35,"item_id":"voidsteel_damage_potion","strength_pct":16,"tier_index":13},{"boost_hits":35,"item_id":"wyrmforged_damage_potion","strength_pct":17,"tier_index":14},{"boost_hits":35,"item_id":"ancient_damage_potion","strength_pct":17,"tier_index":15},{"boost_hits":35,"item_id":"ascendant_damage_potion","strength_pct":18,"tier_index":16}],"upgrade_cost_rule":"round_to_5(max(25, item_value * (0.08 + 3.4 * sqrt(next_plus))))","weapon_multiplier_rule":"1 + 2% * min(plus, 50) + 0.5% * max(plus - 50, 0)"}'::jsonb, '{"details":["Every tier from level 1 to level 150 offers exactly one strength potion, named after its tier.","Strength potions now grant a percentage strength boost instead of a flat damage bonus.","The boost applies to your attack after weapon and armour upgrades, before the target''s defence.","Potion recipes, ingredients, Alchemy requirements, crafting experience, crafting durations and boosted-hit counts are unchanged.","Drinking a potion replaces any active potion; boosts never stack and never add together.","An active potion carries over at activation and keeps its remaining hits.","No potion is deleted, converted or re-identified, and every holding, listing and price is preserved.","Healing food is untouched by this release."],"summary":"All 16 strength potions are now listed on one Alchemist ladder with normalised names and an explicit percentage strength boost.","title":"Tomlandia strength potion release"}'::jsonb)
ON CONFLICT (content_version) DO NOTHING;

DO $v6_copy_content$
DECLARE
  target text;
  column_list text;
  projection text;
  copied bigint;
  expected bigint;
BEGIN
  FOREACH target IN ARRAY ARRAY['game_content_tiers', 'game_content_items', 'game_content_recipes', 'game_content_recipe_inputs', 'game_content_nodes', 'game_content_monsters', 'game_content_monster_loot', 'game_content_fish', 'game_content_fishing_spots', 'game_content_quests', 'game_content_bosses', 'game_content_progression_levels'] LOOP
    SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum),
           string_agg(CASE WHEN attname = 'content_version' THEN '''v6'''
                           ELSE quote_ident(attname) END, ', ' ORDER BY attnum)
      INTO column_list, projection
    FROM pg_attribute
    WHERE attrelid = format('public.%I', target)::regclass AND attnum > 0 AND NOT attisdropped;

    EXECUTE format('DELETE FROM public.%I WHERE content_version = %L', target, 'v6');
    EXECUTE format(
      'INSERT INTO public.%I (%s) SELECT %s FROM public.%I WHERE content_version = %L',
      target, column_list, projection, target, 'v5');

    EXECUTE format('SELECT count(*) FROM public.%I WHERE content_version = %L', target, 'v6') INTO copied;
    EXECUTE format('SELECT count(*) FROM public.%I WHERE content_version = %L', target, 'v5') INTO expected;
    IF copied <> expected OR expected = 0 THEN
      RAISE EXCEPTION 'V6 copy of % is incomplete (% of %)', target, copied, expected;
    END IF;
  END LOOP;
END
$v6_copy_content$;

-- ---------------------------------------------------------------------------
-- Potion delta. Nothing is deleted: the 16 stable potions are renamed in place
-- and given their approved strength percentage, so no foreign-key parent row is
-- ever dropped and re-inserted.
-- ---------------------------------------------------------------------------
DELETE FROM public.game_content_migration_rules WHERE content_version = 'v6';

UPDATE public.game_content_items AS item
SET name = updated.name,
    strength_pct = updated.strength_pct
FROM (VALUES
  ('minor_venom_draught', 'Copper Strength Potion', 12),
  ('bronze_damage_potion', 'Bronze Strength Potion', 12),
  ('goblins_fury_tonic', 'Iron Strength Potion', 12),
  ('steel_damage_potion', 'Steel Strength Potion', 12),
  ('serpents_bite_elixir', 'Mithril Strength Potion', 12),
  ('sunsteel_damage_potion', 'Sunsteel Strength Potion', 12),
  ('runite_damage_potion', 'Runite Strength Potion', 12),
  ('shadow_venom', 'Shadowsteel Strength Potion', 13),
  ('froststeel_damage_potion', 'Froststeel Strength Potion', 13),
  ('wyrmsteel_damage_potion', 'Wyrmsteel Strength Potion', 14),
  ('frostfire_brew', 'Glacial Strength Potion', 15),
  ('starsteel_damage_potion', 'Starsteel Strength Potion', 16),
  ('voidsteel_damage_potion', 'Voidsteel Strength Potion', 16),
  ('wyrmforged_damage_potion', 'Wyrmforged Strength Potion', 17),
  ('ancient_damage_potion', 'Ancient Strength Potion', 17),
  ('ascendant_damage_potion', 'Ascendant Strength Potion', 18)
) AS updated(id, name, strength_pct)
WHERE item.content_version = 'v6'
  AND item.id = updated.id;

