DO $v6_stage_content_exit$
BEGIN
  IF (SELECT status FROM public.game_content_versions WHERE content_version = 'v6') <> 'staged' THEN
    RAISE EXCEPTION 'V6 content must remain staged after step 1';
  END IF;
  IF (SELECT manifest_hash FROM public.game_content_versions WHERE content_version = 'v6') <> 'd87267194b34a7eba300115adfa29600d1d63f52daad4e0e96b947414e673d9e' THEN
    RAISE EXCEPTION 'V6 manifest hash was not recorded';
  END IF;
  IF (SELECT count(*) FROM public.game_content_items WHERE content_version = 'v6') <> 173 THEN
    RAISE EXCEPTION 'V6 must stage exactly 173 items';
  END IF;
  IF (SELECT count(*) FROM public.game_content_items WHERE content_version = 'v6' AND kind = 'potion') <> 16 THEN
    RAISE EXCEPTION 'V6 must stage exactly 16 potions';
  END IF;
  IF (SELECT count(*) FROM public.game_content_items
      WHERE content_version = 'v6' AND kind = 'potion' AND id = ANY (ARRAY['ancient_damage_potion', 'ascendant_damage_potion', 'bronze_damage_potion', 'frostfire_brew', 'froststeel_damage_potion', 'goblins_fury_tonic', 'minor_venom_draught', 'runite_damage_potion', 'serpents_bite_elixir', 'shadow_venom', 'starsteel_damage_potion', 'steel_damage_potion', 'sunsteel_damage_potion', 'voidsteel_damage_potion', 'wyrmforged_damage_potion', 'wyrmsteel_damage_potion']::text[])) <> 16 THEN
    RAISE EXCEPTION 'V6 potion ids are not the approved stable ids';
  END IF;
  IF (SELECT count(DISTINCT tier_index) FROM public.game_content_items
      WHERE content_version = 'v6' AND kind = 'potion') <> 16 THEN
    RAISE EXCEPTION 'V6 must publish exactly one potion per tier';
  END IF;
  IF EXISTS (SELECT 1 FROM public.game_content_items
             WHERE content_version = 'v6' AND kind = 'potion' AND (strength_pct <= 0 OR boost_hits <= 0)) THEN
    RAISE EXCEPTION 'Every V6 potion needs a positive strength percentage and hit count';
  END IF;
  IF EXISTS (
    SELECT 1 FROM (
      SELECT strength_pct, tier_index, lag(strength_pct) OVER (ORDER BY tier_index) AS previous_pct
      FROM public.game_content_items WHERE content_version = 'v6' AND kind = 'potion'
    ) AS ladder
    WHERE previous_pct IS NOT NULL AND strength_pct < previous_pct
  ) THEN
    RAISE EXCEPTION 'V6 strength progression is not non-decreasing';
  END IF;
  IF EXISTS (SELECT 1 FROM public.game_content_items
             WHERE content_version = 'v6' AND kind <> 'potion' AND strength_pct <> 0) THEN
    RAISE EXCEPTION 'Only V6 potions may carry a strength percentage';
  END IF;
  IF (SELECT count(*) FROM public.game_content_recipes WHERE content_version = 'v6') <> 108 THEN
    RAISE EXCEPTION 'V6 must stage exactly 108 recipes';
  END IF;
  IF (SELECT count(*) FROM public.game_content_recipe_inputs WHERE content_version = 'v6') <> 245 THEN
    RAISE EXCEPTION 'V6 recipe inputs are incomplete';
  END IF;
  IF (SELECT count(*) FROM public.game_content_recipes
      WHERE content_version = 'v6' AND output_item_id = ANY (ARRAY['ancient_damage_potion', 'ascendant_damage_potion', 'bronze_damage_potion', 'frostfire_brew', 'froststeel_damage_potion', 'goblins_fury_tonic', 'minor_venom_draught', 'runite_damage_potion', 'serpents_bite_elixir', 'shadow_venom', 'starsteel_damage_potion', 'steel_damage_potion', 'sunsteel_damage_potion', 'voidsteel_damage_potion', 'wyrmforged_damage_potion', 'wyrmsteel_damage_potion']::text[]) AND skill = 'alchemy') <> 16 THEN
    RAISE EXCEPTION 'V6 must stage exactly 16 Alchemy potion recipes';
  END IF;
  -- Every ingredient must exist, be active and be reachable at or below the
  -- recipe's own Alchemy requirement.
  IF EXISTS (
    SELECT 1
    FROM public.game_content_recipes AS recipe
    JOIN public.game_content_recipe_inputs AS input
      ON input.content_version = recipe.content_version AND input.recipe_id = recipe.id
    LEFT JOIN public.game_content_items AS ingredient
      ON ingredient.content_version = recipe.content_version AND ingredient.id = input.item_id
    WHERE recipe.content_version = 'v6'
      AND recipe.output_item_id = ANY (ARRAY['ancient_damage_potion', 'ascendant_damage_potion', 'bronze_damage_potion', 'frostfire_brew', 'froststeel_damage_potion', 'goblins_fury_tonic', 'minor_venom_draught', 'runite_damage_potion', 'serpents_bite_elixir', 'shadow_venom', 'starsteel_damage_potion', 'steel_damage_potion', 'sunsteel_damage_potion', 'voidsteel_damage_potion', 'wyrmforged_damage_potion', 'wyrmsteel_damage_potion']::text[])
      AND (ingredient.id IS NULL OR NOT ingredient.active OR input.qty <= 0)
  ) THEN
    RAISE EXCEPTION 'A V6 potion recipe uses an undefined, inactive or empty ingredient';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.game_content_recipe_inputs
    WHERE content_version = 'v6'
      AND item_id NOT IN (SELECT id FROM public.game_content_items WHERE content_version = 'v6')
  ) OR EXISTS (
    SELECT 1 FROM public.game_content_recipes
    WHERE content_version = 'v6'
      AND output_item_id NOT IN (SELECT id FROM public.game_content_items WHERE content_version = 'v6')
  ) THEN
    RAISE EXCEPTION 'A staged V6 recipe references an item v6 does not define';
  END IF;
  IF (SELECT count(*) FROM public.game_content_items WHERE content_version = 'v5') <> 173 THEN
    RAISE EXCEPTION 'V6 staging modified the v5 catalogue';
  END IF;
  IF EXISTS (SELECT 1 FROM public.game_content_items WHERE content_version = 'v5' AND strength_pct <> 0) THEN
    RAISE EXCEPTION 'V6 staging must not give v5 a strength percentage';
  END IF;
END
$v6_stage_content_exit$;

COMMIT;
